function versionTest
% 获取MATLAB版本
versionStr = version('-release');
versionYear = str2double(versionStr(1:4));

% 判断MATLAB版本是否为2022a或以上
if (versionYear < 2022)
% 如果版本过低，弹出提示框
warndlg('该代码需使用MATLAB 2022及更新版本运行', '版本警告');
end
end